CREATE TABLE IF NOT EXISTS users(id VARCHAR(191) PRIMARY KEY,email VARCHAR(254) UNIQUE NOT NULL,name VARCHAR(191) NOT NULL,password VARCHAR(191) NOT NULL,role VARCHAR(191) DEFAULT 'member',verified BIGINT DEFAULT 0,created BIGINT NOT NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS sessions(token VARCHAR(191) PRIMARY KEY,user_id VARCHAR(191) NOT NULL,expires BIGINT NOT NULL, CONSTRAINT sessions_user FOREIGN KEY(user_id) REFERENCES users(id) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS tokens(token VARCHAR(191) PRIMARY KEY,user_id VARCHAR(191),kind VARCHAR(191) NOT NULL,email VARCHAR(254),expires BIGINT NOT NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS applications(user_id VARCHAR(191) PRIMARY KEY,plan VARCHAR(191) NOT NULL,cycle VARCHAR(191) NOT NULL,motivation VARCHAR(512) NOT NULL,support VARCHAR(512) NOT NULL DEFAULT '',status VARCHAR(191) NOT NULL DEFAULT 'pending',created BIGINT NOT NULL, CONSTRAINT applications_user FOREIGN KEY(user_id) REFERENCES users(id) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS memberships(user_id VARCHAR(191) PRIMARY KEY,plan VARCHAR(191) NOT NULL,cycle VARCHAR(191) NOT NULL,status VARCHAR(191) NOT NULL,`until` BIGINT NOT NULL DEFAULT 0,subscription VARCHAR(191),customer VARCHAR(191),cancel_end BIGINT DEFAULT 0,started BIGINT DEFAULT 0, CONSTRAINT memberships_user FOREIGN KEY(user_id) REFERENCES users(id) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS events(id VARCHAR(191) PRIMARY KEY,payload LONGTEXT NOT NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS instructors(id VARCHAR(191) PRIMARY KEY,payload LONGTEXT NOT NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS bookings(id VARCHAR(191) PRIMARY KEY,user_id VARCHAR(191) NOT NULL,event_id VARCHAR(191) NOT NULL,status VARCHAR(191) NOT NULL,price BIGINT NOT NULL,attended BIGINT DEFAULT 0,benefit VARCHAR(191) DEFAULT '',created BIGINT NOT NULL,expires BIGINT NOT NULL DEFAULT 0,
 active_booking TINYINT GENERATED ALWAYS AS (CASE WHEN status IN ('pending','confirmed','refund_requested') THEN 1 ELSE NULL END) STORED,
 UNIQUE KEY one_active_booking(user_id,event_id,active_booking),
 CONSTRAINT booking_user FOREIGN KEY(user_id) REFERENCES users(id),
 CONSTRAINT booking_event FOREIGN KEY(event_id) REFERENCES events(id)
 ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS orders(id VARCHAR(191) PRIMARY KEY,user_id VARCHAR(191) NOT NULL,kind VARCHAR(191) NOT NULL,target VARCHAR(512) NOT NULL,amount BIGINT NOT NULL,status VARCHAR(191) NOT NULL,session VARCHAR(191),payment VARCHAR(191),created BIGINT NOT NULL,expires BIGINT NOT NULL, CONSTRAINT orders_user FOREIGN KEY(user_id) REFERENCES users(id) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS subscribers(email VARCHAR(254) PRIMARY KEY,name VARCHAR(191) NOT NULL,status VARCHAR(191) NOT NULL,consent BIGINT NOT NULL,token VARCHAR(191) NOT NULL,created BIGINT NOT NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS webhook_events(id VARCHAR(191) PRIMARY KEY,created BIGINT NOT NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS mail(id VARCHAR(191) PRIMARY KEY,email VARCHAR(254) NOT NULL,subject VARCHAR(512) NOT NULL,body LONGTEXT NOT NULL,status VARCHAR(191) DEFAULT 'queued',created BIGINT NOT NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS badges(user_id VARCHAR(191) NOT NULL,badge VARCHAR(191) NOT NULL,created BIGINT NOT NULL,PRIMARY KEY(user_id,badge), CONSTRAINT badges_user FOREIGN KEY(user_id) REFERENCES users(id) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS requests(id VARCHAR(191) PRIMARY KEY,user_id VARCHAR(191) NOT NULL,kind VARCHAR(191) NOT NULL,target VARCHAR(512) NOT NULL,status VARCHAR(191) DEFAULT 'pending',reason VARCHAR(512) NOT NULL,created BIGINT NOT NULL, CONSTRAINT requests_user FOREIGN KEY(user_id) REFERENCES users(id) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS audit(id BIGINT PRIMARY KEY AUTO_INCREMENT,actor VARCHAR(191) NOT NULL,action VARCHAR(191) NOT NULL,target VARCHAR(512) NOT NULL,created BIGINT NOT NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS app_lock(id INT PRIMARY KEY) ENGINE=InnoDB;
INSERT INTO app_lock(id) VALUES(1) ON DUPLICATE KEY UPDATE id=id;
